const ORDER = ["2","3","4","5","6","7","8","9","T","J","Q","K","A"];

function handClass(cards: string[]) {
  const ranks = cards.map((card) => card.slice(0, -1).replace("10", "T")).sort((a, b) => ORDER.indexOf(b) - ORDER.indexOf(a));
  if (ranks[0] === ranks[1]) return ranks.join("");
  return `${ranks.join("")}${cards[0].slice(-1) === cards[1].slice(-1) ? "s" : "o"}`;
}

export function preflopResult(cards: string[], opponents: number): ExactResult {
  const key = handClass(cards);
  const rates = PREFLOP[key];
  if (!rates) throw new Error(`没有找到翻牌前牌型 ${key}`);
  const [win, tie] = rates;
  const base = { win, tie, lose:100-win-tie, equity:win+tie/2, samples:169, categories:Array(9).fill(0), bestHand:key, opponents, method:"preflop" as const };
  if (opponents === 1) return base;
  const calibrated = PREFLOP_MULTIWAY[key]?.[opponents - 2];
  if (!calibrated) throw new Error(`没有找到翻牌前校准牌型 ${key}`);
  const [tableWin, tableTie, tableEquity] = calibrated;
  return {
    ...base,
    table: {
      win: tableWin,
      tie: tableTie,
      lose: 100 - tableWin - tableTie,
      equity: tableEquity,
      method: "preflop_monte_carlo",
      samples: PREFLOP_CALIBRATION_TRIALS,
    },
  };
}

export const PREFLOP_CLASS_COUNT = Object.keys(PREFLOP).length;
